import React, { useState, useEffect, useRef } from "react";
import emailjs from "@emailjs/browser";


/* ================= MAIN APP ================= */

export default function ValentineApp() {

    const [page, setPage] = useState("start");

    useEffect(() => {
        emailjs.init("aEbujbuY5ZtX1sDQq");
    }, []);


    return (
        <div className="valentine-container">

            <div className="app-content">

                {page === "start" && (
                    <StartPage onStart={() => setPage("home")} />
                )}

                {page === "home" && (
                    <HomePage onYes={() => setPage("game")} />
                )}

                {page === "game" && (
                    <GamePage />
                )}

            </div>

            <style>{styles}</style>

        </div>
    );
}


/* ================= START PAGE ================= */

function StartPage({ onStart }) {

    return (
        <div className="start-page">

            <div className="start-card">

                <h2 className="start-title">
                    Hi there 💕
                </h2>

                <p className="start-sub">
                    Touch my head to continue 😺
                </p>


                {/* CAT IMAGE */}
                <div className="cat-box">

                    <img
                        src="/cat.jpg"
                        alt="Cute Cat"
                        className="cat-img"
                    />

                    {/* Head Button */}
                    <button
                        className="cat-head-btn"
                        onClick={onStart}
                        onTouchStart={onStart}
                    />
                </div>


                <p className="start-note">
                    Sound will be enabled ✨
                </p>

            </div>

        </div>
    );
}



/* ================= HOME PAGE ================= */

function HomePage({ onYes }) {

    const [pos, setPos] = useState({ x: 0, y: 0 });

    const btnRef = useRef(null);
    const yesRef = useRef(null);

    const unlocked = useRef(false);

    const noSound = useRef(null);
    const yesSound = useRef(null);


    /* AUDIO INIT */

    useEffect(() => {

        const noAudio = new Audio("/sounds/no.mp3");
        noAudio.muted = true;

        const yesAudio = new Audio("/sounds/yes-hover.mp3");
        yesAudio.muted = true;

        noSound.current = noAudio;
        yesSound.current = yesAudio;


        const unlock = async () => {

            if (unlocked.current) return;

            try {

                await noSound.current.play();
                noSound.current.pause();
                noSound.current.muted = false;

                await yesSound.current.play();
                yesSound.current.pause();
                yesSound.current.muted = false;

                unlocked.current = true;

            } catch {}

            document.removeEventListener("click", unlock);
            document.removeEventListener("touchstart", unlock);

        };


        document.addEventListener("click", unlock);
        document.addEventListener("touchstart", unlock);

        return () => {
            document.removeEventListener("click", unlock);
            document.removeEventListener("touchstart", unlock);
        };

    }, []);



    /* YES SOUND */

    const playYes = () => {

        if (yesSound.current && unlocked.current) {

            yesSound.current.currentTime = 0;
            yesSound.current.play().catch(() => {});
        }
    };


    const stopYes = () => {

        if (yesSound.current) {

            yesSound.current.pause();
            yesSound.current.currentTime = 0;
        }
    };



    /* MOVE NO */

    const move = () => {

        const noBtn = btnRef.current;
        const yesBtn = yesRef.current;

        if (!noBtn || !yesBtn) return;


        if (noSound.current && unlocked.current) {
            noSound.current.currentTime = 0;
            noSound.current.play().catch(()=>{});
        }


        const rect = noBtn.getBoundingClientRect();
        const yesRect = yesBtn.getBoundingClientRect();

        const W = window.innerWidth;
        const H = window.innerHeight;

        const margin = 20;
        const minJump = 180;


        let newX = pos.x;
        let newY = pos.y;

        let tries = 0;


        while (tries < 30) {

            tries++;

            const dx =
                (Math.random() < .5 ? -1 : 1) *
                (minJump + Math.random()*200);

            const dy =
                (Math.random() < .5 ? -1 : 1) *
                (minJump + Math.random()*150);


            const l = rect.left + dx;
            const r = l + rect.width;
            const t = rect.top + dy;
            const b = t + rect.height;


            if (
                l < margin ||
                r > W - margin ||
                t < margin ||
                b > H - margin
            ) continue;


            const overlap =
                r > yesRect.left &&
                l < yesRect.right &&
                b > yesRect.top &&
                t < yesRect.bottom;

            if (overlap) continue;


            newX = pos.x + dx;
            newY = pos.y + dy;

            break;
        }


        setPos({ x:newX, y:newY });
    };




    return (
        <div className="home-page">

            <h1 className="title">
                Will you be my Valentine? 💝
            </h1>


            {/* YES */}

            <button
                ref={yesRef}
                className="main-btn yes-btn"
                onClick={onYes}

                onMouseEnter={playYes}
                onMouseLeave={stopYes}

                onTouchStart={playYes}
                onTouchEnd={stopYes}
            >

                <span className="btn-text">YES 💖</span>
                <span className="btn-sub">Don't be shy 😉</span>

            </button>



            {/* NO */}

            <button
                ref={btnRef}
                className="main-btn no-btn"
                onMouseEnter={move}
                onClick={move}
                onTouchStart={move}

                style={{
                    transform:`translate(${pos.x}px,${pos.y}px)`
                }}
            >

                <span className="btn-text">NO 😜</span>

            </button>

        </div>
    );
}



/* ================= GAME ================= */

function GamePage(){

    const [started,setStarted] = useState(false);
    const iframeRef = useRef(null);
    const [key,setKey] = useState(0);

    const mobile =
        window.matchMedia("(pointer:coarse)").matches;


    const start = ()=>{
        setStarted(true);
        setKey(k=>k+1);

        setTimeout(()=>{
            iframeRef.current?.focus();
        },200);
    };


    const retry = e =>{

        e.target.disabled = true;

        setTimeout(()=>{
            e.target.disabled=false;
        },50);

        setKey(k=>k+1);
    };



    return(
        <div className="game-page">

            {!started && (

                <button
                    className="main-btn no-btn"
                    onClick={start}
                >
                    ▶ Start Game
                </button>

            )}


            {started && (

                <>

                    <div className="game-frame">

                        <iframe
                            key={key}
                            ref={iframeRef}
                            src="/dino.html"
                            title="Game"
                        />

                    </div>


                    <button
                        className="main-btn no-btn"
                        onClick={retry}
                    >
                        🔄 Retry
                    </button>

                </>
            )}


            <p className="hint">

                {!started
                    ? "Press Start 😄"
                    : mobile
                        ? "Tap = Jump | Swipe ↓ = Duck 📱"
                        : "SPACE = Jump | ↓ = Duck 💻"
                }

            </p>

        </div>
    );
}



/* ================= STYLES ================= */

const styles = `

@import url('https://fonts.googleapis.com/css2?family=Pacifico&family=Nunito:wght@400;600;700&display=swap');

*{
  margin:0;
  padding:0;
  box-sizing:border-box;
}

body{
  font-family:"Nunito",sans-serif;
}


/* BACKGROUND */

.valentine-container{

  min-height:100vh;

  background:linear-gradient(
    135deg,
    #fff0f6,
    #ffe4ec,
    #ffd6e8
  );
}


.app-content{
  position:relative;
  z-index:5;
}


/* ================= START ================= */

.start-page{

  min-height:100vh;

  display:flex;
  justify-content:center;
  align-items:center;
}


.start-card{

  background:rgba(255,255,255,.95);

  padding:35px 30px;

  border-radius:28px;

  width:90%;
  max-width:420px;

  text-align:center;

  box-shadow:
    0 25px 50px rgba(255,107,157,.25);
}


.start-title{

  font-family:"Pacifico";
  font-size:2.4rem;
  color:#ff5c8a;
}


.start-sub{

  font-size:1rem;
  color:#ff7aa2;
  margin:8px 0 18px;
}


/* CAT */

.cat-box{

  position:relative;

  width:260px;

  margin:0 auto 20px;

  animation:float 3s ease-in-out infinite;
}


.cat-img{

  width:100%;

  border-radius:18px;

  box-shadow:
    0 15px 35px rgba(0,0,0,.25);

  pointer-events:none;
}


/* HEAD BUTTON */

.cat-head-btn{

  position:absolute;

  top:5%;
  left:20%;

  width:60%;
  height:35%;

  border:none;
  background:transparent;

  border-radius:50%;

  cursor:pointer;

  animation:wiggle 2s ease-in-out infinite;
}


.cat-head-btnn-btn::after{

  content:"";

  position:absolute;
  inset:0;

  border-radius:50%;

  box-shadow:
    0 0 30px rgba(255,120,170,.7);

  opacity:.7;
}


.start-note{

  font-size:.9rem;
  opacity:.7;
  color:#ff5c8a;
}


/* ================= HOME ================= */

.home-page{

  min-height:100vh;

  display:flex;
  flex-direction:column;
  align-items:center;
  justify-content:center;

  gap:35px;

  text-align:center;
}


.title{

  font-family:"Pacifico";
  font-size:3rem;
  color:#ff5c8a;
}


/* BUTTONS */

.main-btn{

  width:180px;
  height:60px;

  border:none;
  border-radius:40px;

  background:linear-gradient(
    135deg,
    #ff7aa2,
    #ff4d88
  );

  color:white;

  cursor:pointer;

  display:flex;
  flex-direction:column;
  align-items:center;
  justify-content:center;

  box-shadow:
    0 8px 20px rgba(255,107,157,.35);

  transition:.25s;
}


.main-btn:hover{
  transform:translateY(-4px) scale(1.05);
}

.main-btn:active{
  transform:scale(.95);
}


.btn-text{

  font-size:1.4rem;
  font-weight:700;
  letter-spacing:1.2px;
}


.btn-sub{

  font-size:.7rem;
  opacity:0;
  height:0;
  transition:.25s;
}


.yes-btn:hover .btn-sub{
  opacity:1;
  height:12px;
}


.no-btn:hover{
  transform:translateY(-4px) rotate(-2deg) scale(1.05);
}


/* ================= GAME ================= */

.game-page{

  min-height:100vh;

  display:flex;
  flex-direction:column;
  align-items:center;

  gap:20px;

  padding-top:120px;
}


.game-frame{

  width:100%;
  max-width:720px;

  aspect-ratio:720/445;

  border-radius:18px;

  overflow:hidden;

  background:black;

  box-shadow:
    0 15px 35px rgba(0,0,0,.3);
}


.game-frame iframe{

  width:100%;
  height:100%;
  border:none;
}


.hint{
  opacity:.7;
  text-align:center;
}


/* ANIMATIONS */

@keyframes float{

  0%{transform:translateY(0);}
  50%{transform:translateY(-8px);}
  100%{transform:translateY(0);}
}


@keyframes wiggle{

  0%{transform:rotate(0);}
  25%{transform:rotate(3deg);}
  50%{transform:rotate(-3deg);}
  75%{transform:rotate(2deg);}
  100%{transform:rotate(0);}
}


/* MOBILE */

@media(max-width:600px){

  .main-btn{
    width:150px;
    height:52px;
  }

  .btn-text{
    font-size:1.2rem;
  }

  .cat-box{
    width:220px;
  }

}
`;
